    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: A patient has a heart rate of 150 bpm. The rhythm is regular, the QRS is narrow, and P-waves are not clearly seen. The most likely diagnosis is:', '["Sinus Tachycardia", "Paroxysmal Supraventricular Tachycardia (PSVT)", "Atrial Fibrillation", "Ventricular Tachycardia"]', 1, 'PSVT (often AVNRT) typically presents as a regular, narrow-complex tachycardia at ~150-220 bpm with hidden P-waves.'),
    (v_topic_id, '202: "Vagal maneuvers" (like the Valsalva or carotid massage) work by:', '["Increasing sympathetic tone", "Stimulating the vagus nerve to slow conduction through the AV node", "Directly stopping atrial depolarization", "Increasing coronary blood flow"]', 1, 'The vagus nerve provides parasympathetic innervation to the SA and AV nodes. Stimulating it delays AV conduction.'),
    (v_topic_id, '203: When performing carotid sinus massage, what is the most important contraindication to check for first?', '["Hypertension", "Carotid bruits or a history of TIA/Stroke", "Asthma", "Diabetes"]', 1, 'Massage can dislodge an atherosclerotic plaque, leading to a stroke.'),
    (v_topic_id, '204: In Atrial Flutter, if the atrial rate is 300 bpm and the ventricular rate is 75 bpm, the conduction ratio is:', '["2:1", "3:1", "4:1", "Variable"]', 2, '300 divided by 75 equals 4, so every 4th flutter wave is conducted.'),
    (v_topic_id, '205: A "Wide-complex tachycardia" should be assumed to be _____ until proven otherwise, especially in a patient with underlying heart disease.', '["SVT with aberrancy", "Ventricular Tachycardia (VT)", "Sinus Tachycardia", "Bundle Branch Block"]', 1, 'VT is the most dangerous and common cause of regular wide-complex tachycardia in adults with structural heart disease.'),
    (v_topic_id, '206: "Torsades de Pointes" is a polymorphic VT associated with which ECG finding?', '["Short PR interval", "Prolonged QT interval", "Delta waves", "Pathological Q-waves"]', 1, 'Torsades ("twisting of the points") is classically triggered by a long QT interval.'),
    (v_topic_id, '207: What is the immediate treatment of choice for a patient in pulseless Ventricular Tachycardia or Ventricular Fibrillation?', '["Amiodarone", "Lidocaine", "Unsynchronized cardioversion (Defibrillation)", "Synchronized cardioversion"]', 2, 'Defibrillation is the only effective treatment for these shockable arrest rhythms.'),
    (v_topic_id, '208: "Synchronized cardioversion" is used for which of the following rhythms when the patient is unstable but has a pulse?', '["Ventricular Fibrillation", "Asystole", "Unstable SVT or VT with a pulse", "PEA"]', 2, 'Synchronization ensures the shock is delivered during the R-wave, avoiding the vulnerable T-wave period (the R-on-T phenomenon).'),
    (v_topic_id, '209: A 70-year-old patient has a heart rate of 45 bpm. The ECG shows P-waves at 80 bpm and QRS complexes at 45 bpm with no consistent PR interval. This is:', '["First-degree AV block", "Mobitz II AV block", "Third-degree (Complete) AV block", "Wenckebach"]', 2, 'Total dissociation between P-waves and QRS complexes defines complete heart block.'),
    (v_topic_id, '210: What is the most appropriate long-term treatment for symptomatic Mobitz Type II or Third-degree AV block?', '["Atropine", "Beta-blockers", "Permanent Pacemaker", "Cardioversion"]', 2, 'These high-grade blocks are usually permanent and carry a high risk of cardiac arrest.'),
    (v_topic_id, '211: "Atrial Fibrillation with a rapid ventricular response (RVR)" means:', '["The atrial rate is very fast", "The ventricular rate is > 100 bpm in the setting of AFib", "The PR interval is short", "The QRS is wide"]', 1, 'RVR refers to the ventricular rate, not the atrial rate.'),
    (v_topic_id, '212: Which medication is often used for acute "rate control" in a stable patient with Atrial Fibrillation RVR?', '["Amiodarone", "Epinephrine", "Diltiazem or Metoprolol", "Atropine"]', 2, 'Calcium channel blockers and beta-blockers slow AV node conduction.'),
    (v_topic_id, '213: The CHA2DS2-VASc score is used in Atrial Fibrillation to determine the risk of:', '["Heart failure", "Stroke (thromboembolism)", "Ventricular tachycardia", "Bleeding"]', 1, 'It helps clinicians decide if a patient needs anticoagulation.'),
    (v_topic_id, '214: "Lone Atrial Fibrillation" refers to AFib in a patient:', '["Who is older than 80", "Who has no structural heart disease and is < 60 years old", "Who has severe mitral stenosis", "Who is in a coma"]', 1, 'Lone AFib implies a lower risk of stroke.'),
    (v_topic_id, '215: "Valvular Atrial Fibrillation" is specifically defined as AFib in the presence of:', '["Any heart murmur", "Moderate-to-severe mitral stenosis or a mechanical heart valve", "Aortic regurgitation", "Patent ductus arteriosus"]', 1, 'This distinction is important because these patients MUST be on Warfarin, not NOACs.'),
    (v_topic_id, '216: A "Holiday Heart" rhythm is most commonly:', '["Sinus Bradycardia", "Atrial Fibrillation triggered by excessive alcohol consumption", "Ventricular Fibrillation", "WPW syndrome"]', 1, 'Acute alcohol ingestion is a common trigger for paroxysmal AFib in otherwise healthy individuals.'),
    (v_topic_id, '217: A "PAC" (Premature Atrial Contraction) that fails to conduct to the ventricles because the AV node is still refractory is called a:', '["Non-conducted PAC", "Mobitz II block", "Sinus arrest", "Escape beat"]', 0, 'This appears as an early P-wave that is not followed by a QRS, often mistaken for a sinus pause.'),
    (v_topic_id, '218: "Interpolated PVC" is a PVC that:', '["Occurs between two normal sinus beats without disturbing the underlying sinus rhythm", "Causes a compensatory pause", "Is followed by a PAC", "Is very wide"]', 0, 'This is a "sandwich" PVC that happens so early it doesn''t interfere with the next sinus impulse.'),
    (v_topic_id, '219: "Multifocal PVCs" means:', '["The PVCs occur at a fast rate", "The PVCs have different shapes, indicating they originate from different spots in the ventricles", "There are more than 10 PVCs per minute", "The PVCs are all identical"]', 1, 'Multifocal PVCs indicate greater ventricular irritability.'),
    (v_topic_id, '220: A "Rhythm Strip" is usually which lead recorded over a longer period of time?', '["Lead I", "Lead II", "Lead aVR", "Lead V1"]', 1, 'Lead II is most commonly used for rhythm analysis because the P-waves are usually most prominent there.'),
    (v_topic_id, '221: "Parasystole" is a rhythm where:', '["The SA node is the only pacemaker", "An ectopic focus fires independently of the sinus rhythm, often showing varying coupling intervals", "The heart rate is 300 bpm", "There are no P-waves"]', 1, 'Parasystole involves a "protected" ectopic focus that doesn''t get reset by the sinus beats.'),
    (v_topic_id, '222: "Accelerated Idioventricular Rhythm" (AIVR) is a ventricular rhythm with a rate of 40-100 bpm. It is most commonly seen:', '["During an acute MI", "Immediately after reperfusion of an occluded coronary artery", "In healthy athletes", "During sleep"]', 1, 'AIVR is a classic "reperfusion arrhythmia" and is usually benign and self-limiting.'),
    (v_topic_id, '223: "Ventricular Fibrillation" (VF) is characterized on ECG by:', '["A regular, wide-complex tachycardia", "A rapid, chaotic, irregular wavy baseline without discernible QRS complexes", "A flat line", "Tall, peaked T-waves"]', 1, 'VF is a state of electrical chaos; there is no coordinated contraction and no cardiac output.'),
    (v_topic_id, '224: "Asystole" is defined as:', '["A heart rate < 20 bpm", "A total absence of ventricular electrical activity (flat line)", "Ventricular fibrillation", "An extremely wide QRS"]', 1, 'Asystole is a non-shockable arrest rhythm.'),
    (v_topic_id, '225: "Pulseless Electrical Activity" (PEA) refers to a situation where:', '["The ECG shows an organized rhythm (like sinus), but the patient has no pulse", "The ECG shows VF", "The heart rate is 200 bpm", "The QRS is 0.20 seconds wide"]', 0, 'PEA means the electrical system is working, but the mechanical system is not (often due to reversible causes like hypovolemia or tamponade).'),
    (v_topic_id, '226: The "6 H''s and 5 T''s" are the common reversible causes of:', '["Atrial Fibrillation", "PEA and Asystole", "Sinus Tachycardia", "LBBB"]', 1, 'This mnemonic helps clinicians quickly run through causes like Hypoxia, Tension Pneumothorax, Tamponade, etc.'),
    (v_topic_id, '227: In a patient with "Long QT Syndrome", what is the primary risk of using certain medications like Erythromycin or Haloperidol?', '["They can cause heart block", "They can further prolong the QT interval and trigger Torsades de Pointes", "They cause hypertension", "They make the QRS wider"]', 1, 'Many common drugs can prolong the QT interval and are contraindicated in patients with Long QT Syndrome.'),
    (v_topic_id, '228: "Short QT Syndrome" is also a risk factor for sudden death. It is defined as a QTc less than:', '["0.30 seconds", "0.33 seconds", "0.36 seconds", "0.39 seconds"]', 2, 'Short QT is much rarer than Long QT but also increases the risk of AFib and VF.'),
    (v_topic_id, '229: What is the "Intrinsicoid Deflection" (or R-wave peak time)?', '["The time from the start of the P-wave to the QRS", "The time from the start of the QRS to the peak of the R-wave", "The duration of the T-wave", "The time between the S and T waves"]', 1, 'Prolonged intrinsicoid deflection (> 0.05s in lateral leads) is a supporting sign for LVH.'),
    (v_topic_id, '230: "Electrical Alternans" involving both the QRS complex AND the P-wave is highly specific for:', '["Pericardial Effusion with Cardiac Tamponade", "Pulmonary Embolism", "Severe COPD", "Hyperkalemia"]', 0, 'This reflects the massive "swinging" of the entire heart within a large fluid-filled pericardial sac.'),
    (v_topic_id, '231: "Cannon A-waves" in the jugular venous pulse are a physical exam finding that suggests:', '["Atrial Fibrillation", "AV dissociation (e.g., Third-degree block or VT)", "Mitral Stenosis", "Tricuspid Regurgitation"]', 1, 'Cannon A-waves occur when the atrium contracts against a closed tricuspid valve during ventricular systole.'),
    (v_topic_id, '232: A "fusion beat" provides definitive evidence for which rhythm in a patient with wide-complex tachycardia?', '["SVT", "Ventricular Tachycardia", "Sinus Tachycardia", "WPW"]', 1, 'Only VT allows for the "collision" of a supraventricular and a ventricular impulse.'),
    (v_topic_id, '233: "Capture beats" are also known as:', '["Dressler beats", "Osborn beats", "Delta waves", "F waves"]', 0, 'Capture beats are a classic sign of VT.'),
    (v_topic_id, '234: "Brugada Syndrome" is more common in which population?', '["Elderly women", "Young-to-middle-aged males of Southeast Asian descent", "Children with congenital heart disease", "Patients with diabetes"]', 1, 'Brugada is a major cause of Sudden Unexpected Nocturnal Death Syndrome (SUNDS) in these regions.'),
    (v_topic_id, '235: The most common cause of "Left Axis Deviation" in a healthy adult is:', '["Left Anterior Fascicular Block (LAFB)", "Inferior MI", "LVH", "Horizontal heart position (often in obesity)"]', 3, 'While LAFB is a pathological cause, a simple horizontal heart position is very common.'),
    (v_topic_id, '236: "Incomplete RBBB" is defined as an rsR'' pattern in V1 with a QRS duration of:', '["< 0.10 seconds", "0.10 to 0.12 seconds", "> 0.12 seconds", "> 0.15 seconds"]', 1, '0.10-0.12s is considered "incomplete" bundle branch block.'),
    (v_topic_id, '237: A "Non-specific ST-T wave abnormality" (NSSTTW) means:', '["The patient is having an MI", "The changes do not fit a specific diagnostic pattern like ischemia or strain", "The ECG is completely normal", "The patient has a bundle branch block"]', 1, 'This is a common but vague finding that must be interpreted in clinical context.'),
    (v_topic_id, '238: "J-point depression" followed by an upsloping ST segment is usually:', '["A sign of ischemia", "A normal finding during exercise or tachycardia", "Diagnostic of NSTEMI", "A sign of hypercalcemia"]', 1, 'Upsloping depression is far less concerning than horizontal or downsloping depression.'),
    (v_topic_id, '239: A "Prominent R-wave in V1" (R/S ratio > 1) can be seen in which of the following?', '["Right Ventricular Hypertrophy (RVH)", "Posterior MI", "Right Bundle Branch Block (RBBB)", "All of the above"]', 3, 'V1 is the "right-sided" lead; anything that increases right-sided forces or shifts the vector rightward will increase the R-wave in V1.'),
    (v_topic_id, '240: "S-waves in V5 and V6" that are deep and slurred are a hallmark of:', '["Left Bundle Branch Block", "Right Bundle Branch Block", "LVH", "Anterior MI"]', 1, 'The terminal slurred S-wave in lateral leads represents the late, slow depolarization of the right ventricle in RBBB.'),
    (v_topic_id, '241: In LBBB, which lead typically shows a "discordant" (upright) T-wave?', '["Lead I", "Lead V1", "Lead V6", "Lead aVL"]', 1, 'Since the QRS is negative in V1 in LBBB, the T-wave is normally upright.'),
    (v_topic_id, '242: A "discordant" T-wave in a bundle branch block is:', '["Always abnormal", "A normal finding", "A sign of hyperkalemia", "A sign of digitalis effect"]', 1, 'Discordance is the expected secondary repolarization change in BBB.'),
    (v_topic_id, '243: "Concordant" T-waves in a bundle branch block (T-wave in the same direction as the QRS) are:', '["Normal", "Highly suspicious for acute ischemia", "Common in athletes", "A sign of hypocalcemia"]', 1, 'This is a subtle indicator of underlying ischemia/infarction.'),
    (v_topic_id, '244: What is "Vagal-mediated AFib"?', '["AFib that occurs during exercise", "AFib that typically occurs at rest or after a large meal (increased vagal tone)", "AFib caused by stress", "AFib that leads to heart block"]', 1, 'Some patients have AFib triggered by parasympathetic activity rather than sympathetic activity.'),
    (v_topic_id, '245: The most common site of origin for ectopic impulses that trigger Atrial Fibrillation is:', '["The SA node", "The Pulmonary Veins", "The AV junction", "The Coronary Sinus"]', 1, 'Pulmonary vein isolation (ablation) is a standard treatment for refractory AFib.'),
    (v_topic_id, '246: "Esmarch''s maneuver" or "Jaw thrust" is used in an emergency to:', '["Stop a tachycardia", "Open the airway without moving the neck", "Lower blood pressure", "Check for pulses"]', 1, 'This is critical during the initial assessment of a patient who may have an arrhythmia-induced arrest.'),
    (v_topic_id, '247: "Atrial enlargement" is better visualized on ECG than "Atrial hypertrophy" because:', '["The atria are thinner-walled, so they dilate more easily than they thicken", "Atrial cells cannot hypertrophy", "The P-wave only shows conduction speed", "Atria don''t contribute to the ECG"]', 0, 'Dilation has a greater impact on the duration and amplitude of the P-wave.'),
    (v_topic_id, '248: "Biatrial enlargement" (signs of both LAE and RAE) is commonly seen in:', '["Mitral stenosis", "Restrictive cardiomyopathy or complex valvular disease", "Simple hypertension", "Athletes"]', 1, 'Disease affecting both the left and right sides of the heart leads to biatrial signs.'),
    (v_topic_id, '249: In an "Accelerated Idioventricular Rhythm", why is Atropine usually NOT indicated?', '["Because it is too fast", "Because the rhythm is usually benign and transient, and Atropine can trigger faster VT", "Because it is a ventricular rhythm and won''t respond to Atropine", "Because it causes hypertension"]', 1, 'AIVR usually resolves on its own as the underlying sinus rate increases or the ischemia improves.'),
    (v_topic_id, '250: "Tachy-Brady Syndrome" is a classic component of Sick Sinus Syndrome. What is the usual "tachy" rhythm involved?', '["Ventricular Tachycardia", "Paroxysmal Atrial Fibrillation or Flutter", "Sinus Tachycardia", "WPW"]', 1, 'The diseased sinus node allows for escape tachyarrhythmias, followed by profound bradycardia or pauses when the tachyarrhythmia terminates.'),
    (v_topic_id, '251: A "Wide QRS complex" (> 0.12s) can be caused by which of the following?', '["Bundle Branch Block", "Ventricular origin (PVC, VT, Idioventricular)", "Pre-excitation (WPW)", "All of the above"]', 3, 'Anything that bypasses or delays the normal fast-conducting His-Purkinje system will widen the QRS.'),
    (v_topic_id, '252: "Aberrancy" refers to:', '["A permanent bundle branch block", "A temporary, rate-related bundle branch block during a supraventricular rhythm", "A ventricular tachycardia", "A misplaced electrode"]', 1, 'Aberrancy occurs when an impulse arrives at a bundle branch while it is still refractory, usually during a fast rate.'),
    (v_topic_id, '253: In Atrial Flutter, the ventricular response is usually regular. When would it be irregular?', '["If the conduction ratio is constant (e.g., 2:1)", "If the conduction ratio is variable (e.g., switching between 2:1, 3:1, and 4:1)", "If the atrial rate is 300", "Never"]', 1, 'Variable block in Atrial Flutter can mimic the irregularity of Atrial Fibrillation.'),
    (v_topic_id, '254: "Ventricular Parasystole" can be distinguished from simple PVCs because the PVCs in parasystole:', '["Have a fixed coupling interval to the preceding sinus beat", "Have a varying coupling interval and a common denominator between inter-PVC intervals", "Are always narrow", "Occur in bigeminy"]', 1, 'Since the parasystolic focus fires at its own independent rate, its distance from the preceding sinus beat varies.'),
    (v_topic_id, '255: "Torsades de Pointes" literally means:', '["Dance of the ventricles", "Twisting of the points", "Death of the heart", "Fast waves"]', 1, 'This refers to the way the QRS peaks seem to rotate around the isoelectric line.'),
    (v_topic_id, '256: Magnesium Sulfate is the treatment of choice for:', '["Sinus Tachycardia", "Torsades de Pointes", "Atrial Fibrillation", "First-degree block"]', 1, 'Magnesium stabilizes the cardiac membrane and is the gold standard for Torsades.'),
    (v_topic_id, '257: A "Short PR interval" (< 0.12s) WITHOUT a delta wave suggests:', '["WPW syndrome", "Lown-Ganong-Levine (LGL) syndrome", "Mobitz II block", "Hyperkalemia"]', 1, 'LGL uses a fast-conducting bypass tract (James fibers) that enters the bundle of His directly, avoiding the AV node delay without pre-exciting the ventricular muscle.'),
    (v_topic_id, '258: In a patient with "Dextrocardia", why do the precordial leads show decreasing R-wave amplitude from V1 to V6?', '["The heart is getting further away from the electrodes as they move left", "The left ventricle is smaller", "The patient has a bundle branch block", "It is an artifact"]', 0, 'In dextrocardia, V1 is closest to the heart and V6 is furthest away (the opposite of normal).'),
    (v_topic_id, '259: "Situs Inversus" refers to:', '["The heart being on the right side only", "The total reversal of both the heart and the abdominal organs", "The heart being upside down", "The leads being reversed"]', 1, 'Dextrocardia is often part of situs inversus.'),
    (v_topic_id, '260: A "Positive P-wave" in Lead aVR is a strong sign of:', '["Lead reversal (RA/LA)", "Anterior MI", "LBBB", "RVH"]', 0, 'Since the electrical axis of the atria points away from aVR, the P-wave should always be negative unless the leads are swapped.'),
    (v_topic_id, '261: If the "Left Leg" and "Right Arm" electrodes are reversed, which lead will be most affected and potentially become a flat line?', '["Lead I", "Lead II", "Lead III", "Lead aVF"]', 1, 'This is a common lead misplacement error.'),
    (v_topic_id, '262: The "ST-T segment" represents:', '["Atrial repolarization", "Ventricular repolarization", "Ventricular depolarization", "AV node conduction"]', 1, 'The ST segment and T-wave reflect the recovery phase of the ventricles.'),
    (v_topic_id, '263: "Primary T-wave inversion" is due to:', '["Bundle branch blocks", "Myocardial ischemia or inflammation", "Ventricular hypertrophy", "Normal physiology"]', 1, 'Primary changes are due to direct alterations in the repolarization process (like ischemia), unlike secondary changes which are due to abnormal depolarization (like BBB).'),
    (v_topic_id, '264: "Symmetric" T-wave inversion is much more likely to be _____ than asymmetric inversion.', '["Benign", "Ischemic", "Due to hypertrophy", "Normal"]', 1, 'Ischemia typically produces symmetric T-wave changes.'),
    (v_topic_id, '265: "Asymmetric" T-wave inversion (slow downslope, fast upslope) is characteristic of:', '["Ischemia", "Ventricular strain pattern (Hypertrophy)", "Hypokalemia", "Hypercalcemia"]', 1, 'Strain patterns are typically asymmetric.'),
    (v_topic_id, '266: "U-wave inversion" in the precordial leads is highly specific for:', '["Ischemia of the LAD territory", "Hypokalemia", "Digitalis effect", "Exercise"]', 0, 'Inverted U-waves are almost always pathological.'),
    (v_topic_id, '267: A "Tall T-wave" (> 10 mm in precordial leads) can be caused by:', '["Hyperacute MI", "Hyperkalemia", "Normal variant (High-takeoff)", "All of the above"]', 3, 'The clinical context and T-wave shape (broad vs. tented) are key to differentiating these.'),
    (v_topic_id, '268: "QT prolongation" is defined as a QTc greater than:', '["0.40s", "0.44s - 0.46s (depending on gender)", "0.50s", "0.60s"]', 1, '440ms for men and 460ms for women are the standard upper limits.'),
    (v_topic_id, '269: Which of the following can cause "QT prolongation"?', '["Hypokalemia, Hypomagnesemia, Hypocalcemia", "Hyperkalemia", "Hypercalcemia", "Hyperthyroidism"]', 0, 'Low electrolyte levels generally prolong the QT interval.'),
    (v_topic_id, '270: "ST-segment elevation" in the presence of "Pathological Q-waves" in the same leads suggests:', '["Acute MI", "Ventricular Aneurysm (old MI)", "Early repolarization", "Pericarditis"]', 1, 'If the Q-waves are already established and the ST elevation is stable over time, it suggests a chronic aneurysm.'),
    (v_topic_id, '271: "Pseudo-infarction" patterns (Q-waves not due to MI) can be seen in:', '["WPW syndrome", "LVH", "LBBB", "All of the above"]', 3, 'Many conditions can mimic the Q-waves of an old infarction.'),
    (v_topic_id, '272: "Delta waves" in WPW can mimic:', '["Q-waves (pseudo-infarct pattern)", "Bundle branch blocks", "ST elevation", "All of the above"]', 3, 'WPW is a great mimic on the ECG.'),
    (v_topic_id, '273: In a "Right-sided ECG", the precordial leads (V1R-V6R) are placed:', '["On the patient''s back", "In a mirror image of the standard leads across the right chest", "On the right arm", "Only in the 2nd intercostal space"]', 1, 'Right-sided leads are essential for diagnosing RV infarction.'),
    (v_topic_id, '274: A "Posterior ECG" involves placing leads V7, V8, and V9. V7 is located at the:', '["Left midaxillary line", "Left posterior axillary line at the same level as V4-V6", "Right scapular line", "Spine"]', 1, 'This allows for direct observation of the posterior wall.'),
    (v_topic_id, '275: "Lead V3R" and "V4R" are the most useful right-sided leads. They are placed:', '["In the right 3rd and 4th intercostal spaces", "In the right midclavicular and anterior axillary lines", "On the right back", "In the same positions as V3 and V4 but on the right side"]', 3, 'This is the standard technique for a right-sided ECG.'),
    (v_topic_id, '276: A patient has "S1Q3T3" and a new RBBB. Their most likely diagnosis is:', '["Acute MI", "Pulmonary Embolism", "LBBB", "Pericarditis"]', 1, 'The combination of right heart strain findings is highly suggestive of PE.'),
    (v_topic_id, '277: "Right Ventricular Strain" pattern involves T-wave inversions in which leads?', '["I, aVL, V5, V6", "V1, V2, V3 and II, III, aVF", "aVR only", "Lead I only"]', 1, 'The right-sided and inferior leads show repolarization changes in RV strain.'),
    (v_topic_id, '278: In "Hypothermia", the "Osborn wave" (J-wave) is most prominent in which leads?', '["V1 and V2", "Lateral leads (V5, V6, I, aVL)", "Inferior leads", "aVR"]', 1, 'While they can be seen globally, they are often best seen in the lateral precordial leads.'),
    (v_topic_id, '279: "Digitalis toxicity" can cause which of the following rhythms?', '["AV block", "Junctional tachycardia", "Ventricular bigeminy", "All of the above"]', 3, 'Digoxin toxicity can cause almost any arrhythmia, but increased automaticity plus slowed AV conduction is the classic mechanism.'),
    (v_topic_id, '280: "Bidirectional Ventricular Tachycardia" (QRS axis alternates beat-to-beat) is a very rare but classic sign of:', '["Hyperkalemia", "Digitalis Toxicity", "Hypothermia", "Brugada syndrome"]', 1, 'This is a specific, high-risk sign of severe digoxin poisoning.'),
    (v_topic_id, '281: "Quinidine" and other Class Ia antiarrhythmics can cause:', '["Shortened QT", "QT prolongation and Torsades de Pointes", "Narrow QRS", "Sinus Bradycardia"]', 1, 'Class Ia and Class III drugs are the most common pharmacological causes of drug-induced Long QT.'),
    (v_topic_id, '282: "Tricyclic Antidepressant (TCA) overdose" is characterized on ECG by:', '["Short PR interval", "Wide QRS and a tall R-wave in aVR (> 3 mm)", "ST elevation in V1", "Delta waves"]', 1, 'TCA overdose blocks sodium channels, widening the QRS and shifting the terminal axis toward aVR.'),
    (v_topic_id, '283: A tall R-wave in aVR in the setting of an intentional overdose is highly suspicious for:', '["TCA Toxicity", "Aspirin Toxicity", "Acetaminophen Toxicity", "Lithium Toxicity"]', 0, 'The R-wave in aVR (R/S ratio > 0.7 or amplitude > 3 mm) is a sensitive indicator of TCA toxicity.'),
    (v_topic_id, '284: "Hyperkalemia" classically causes T-waves that are:', '["Flattened", "Inverted", "Tall, symmetric, and \"tented\" (peaked)", "Biphasic"]', 2, 'Peaked T-waves are the earliest sign of hyperkalemia.'),
    (v_topic_id, '285: As Potassium levels rise further (> 7-8 mEq/L), what happens to the QRS?', '["It becomes narrower", "It widens and eventually merges with the T-wave to form a \"sine wave\" pattern", "It becomes a delta wave", "It disappears"]', 1, 'The sine wave is a pre-terminal finding in hyperkalemia.'),
    (v_topic_id, '286: In severe Hyperkalemia, what happens to the P-waves?', '["They become taller", "They flatten and eventually disappear (sinoventricular rhythm)", "They become notched", "They become inverted"]', 1, 'Atrial conduction is lost before ventricular conduction in severe hyperkalemia.'),
    (v_topic_id, '287: "Hypokalemia" characteristically shows:', '["Peaked T-waves", "ST depression, flattened T-waves, and prominent U-waves", "Shortened QT", "Delta waves"]', 1, 'As the T-wave flattens and the U-wave grows, it can look like a very long "QU" interval.'),
    (v_topic_id, '288: "Hypercalcemia" on ECG is characterized by:', '["Shortening of the QT interval (primarily the ST segment)", "Prolongation of the QT interval", "Tall T-waves", "Wide QRS"]', 0, 'Hypercalcemia "shrinks" the ST segment.'),
    (v_topic_id, '289: "Hypocalcemia" on ECG is characterized by:', '["Shortening of the QT interval", "Prolongation of the QT interval (primarily the ST segment)", "Tall T-waves", "Osborn waves"]', 1, 'Hypocalcemia "stretches" the ST segment, lengthening the QT interval without changing the T-wave itself.'),
    (v_topic_id, '290: A "Prolonged PR interval" can be caused by:', '["Increased vagal tone", "Beta-blockers or Calcium channel blockers", "AV node ischemia", "All of the above"]', 3, 'Anything that slows conduction through the AV node will prolong the PR interval.'),
    (v_topic_id, '291: "Atrial dissociation" is a rare ECG finding where:', '["The P-waves and QRS are dissociated", "Two independent atrial rhythms are seen (e.g., sinus P-waves and a separate flutter rhythm)", "The atria stop beating", "The P-waves are inverted"]', 1, 'This is usually seen in severely ill patients with advanced heart disease.'),
    (v_topic_id, '292: "Junctional Tachycardia" is often seen in children after cardiac surgery or in adults with:', '["Athletic heart", "Digitalis Toxicity", "COPD", "Pneumonia"]', 1, 'Non-paroxysmal junctional tachycardia is a classic sign of digitalis effect/toxicity.'),
    (v_topic_id, '293: The "Ventricular Rate" in Atrial Flutter is usually a divisor of 300. Which of these is a common rate?', '["100 bpm (3:1)", "150 bpm (2:1)", "75 bpm (4:1)", "All of the above"]', 3, 'Flutter conduction is usually in fixed ratios.'),
    (v_topic_id, '294: A "regularly irregular" rhythm refers to:', '["Atrial Fibrillation", "A rhythm with a repeating pattern of irregularity (e.g., bigeminy or Wenckebach)", "Sinus Tachycardia", "Asystole"]', 1, 'Regularly irregular rhythms have a predictable "skip" or pattern.'),
    (v_topic_id, '295: "Wenckebach" (Mobitz I) is often physiological and seen in:', '["Healthy athletes during sleep", "Acute MI patients", "Patients with high fever", "Hyperthyroidism"]', 0, 'High vagal tone at rest can cause transient Wenckebach in fit individuals.'),
    (v_topic_id, '296: In "Mobitz II" AV block, where is the anatomical site of the block?', '["The SA node", "The AV node", "Below the AV node (His bundle or bundle branches)", "The left atrium"]', 2, 'Mobitz II is almost always a sign of significant infra-nodal conduction system disease.'),
    (v_topic_id, '297: A "Pacemaker-mediated tachycardia" (PMT) occurs when:', '["The pacemaker battery is low", "The pacemaker senses retrograde P-waves and triggers a ventricular beat, creating a re-entrant loop", "The patient exercises too much", "The leads are reversed"]', 1, 'This is an "electronic" re-entrant tachycardia.'),
    (v_topic_id, '298: "Magnet placement" over a permanent pacemaker typically:', '["Turns the pacemaker off", "Switches the pacemaker to a fixed-rate (asynchronous) mode", "Causes a shock to be delivered", "Reprograms the rate"]', 1, 'This is a standard bedside test to check pacemaker function and battery life.'),
    (v_topic_id, '299: A "Pacemaker spike" followed by a wide QRS complex is the normal appearance of a:', '["Dual-chamber pacemaker", "Ventricular-paced beat", "Atrial-paced beat", "Sensing failure"]', 1, 'Ventricular pacing bypasses the His-Purkinje system, resulting in a LBBB-like wide QRS.'),
    (v_topic_id, '300: "Failure to Capture" means:', '["The pacemaker fails to see the heart''s own rhythm", "A pacemaker spike is seen, but no QRS complex follows it", "The pacemaker stops firing", "The heart rate is too fast"]', 1, 'This indicates that the electrical stimulus is not strong enough to depolarize the heart muscle or the leads are displaced.');
